import{_ as e,o as a,c as o,aj as s}from"./chunks/framework.BwH0p-pt.js";const c=JSON.parse('{"title":"Digital Product Passport","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/passport/index.md","filePath":"3.0/passport/index.md","lastUpdated":1785836850000}'),r={name:"3.0/passport/index.md"};function i(n,t,l,d,p,h){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="digital-product-passport" tabindex="-1">Digital Product Passport <a class="header-anchor" href="#digital-product-passport" aria-label="Permalink to &quot;Digital Product Passport&quot;">​</a></h1><p>A <strong>Digital Product Passport (DPP)</strong> is a public page for one of your products, reachable by scanning a QR code, that shows the data a regulator, recycler or customer is entitled to see. UnoPim builds it from the product data you already maintain — you do not re-enter anything.</p><h2 id="what-unopim-gives-you" tabindex="-1">What UnoPim gives you <a class="header-anchor" href="#what-unopim-gives-you" aria-label="Permalink to &quot;What UnoPim gives you&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Passport Templates</strong></td><td>Decide <em>what</em> a passport contains: sections, fields, which attribute each field reads, who may see it, and what is mandatory.</td></tr><tr><td><strong>Public passport page</strong></td><td>A permanent address per product and language, plus a QR code and a machine-readable version for systems that consume it.</td></tr><tr><td><strong>Publish control</strong></td><td>A passport cannot go live in a language while a mandatory field is empty in that language.</td></tr><tr><td><strong>Version history</strong></td><td>Every publish is kept. You can see what a passport said on any date, and withdraw or restore it.</td></tr></tbody></table><h2 id="the-three-pieces" tabindex="-1">The three pieces <a class="header-anchor" href="#the-three-pieces" aria-label="Permalink to &quot;The three pieces&quot;">​</a></h2><ol><li><strong>A passport template</strong> — the definition. Lives in <strong>Catalog → Passports → Templates</strong>.</li><li><strong>An attribute family</strong> — the products the template applies to. A family belongs to exactly one template.</li><li><strong>Your attributes</strong> — where the values actually live. A template field points at one of them.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If your data is already in UnoPim, building a passport is mapping work, not data entry. If a value is missing, it is missing from your catalogue — the passport just makes that visible.</p></div><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Turn the feature on in <a href="./../configuration/system-settings.html">System Settings</a>: go to <strong>Configuration → System Settings</strong>, open the <strong>Digital Product Passport</strong> section, and enable <strong>Product Passport</strong>. To serve the public pages, also enable <strong>Publication</strong> in the same section.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./templates.html">Passport Templates</a> — build or adapt the definition.</li><li><a href="./publishing.html">Publishing a Passport</a> — publish, preview, withdraw, and read the public page.</li><li><a href="./presets.html">Ready-made Templates</a> — the EU battery and general ESPR templates that ship with UnoPim.</li></ul>',11)])])}const g=e(r,[["render",i]]);export{c as __pageData,g as default};
